from datetime import datetime

def parse_date(date_str):
    """Parse date string in format YYYY-MM-DD or YYYY-MM-DD HH:MM:SS"""
    if not date_str or date_str.strip() == '':
        return None
    try:
        # Try with time
        return datetime.strptime(date_str.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            return datetime.strptime(date_str.strip(), '%Y-%m-%d')
        except ValueError:
            return None

# Initialize stats
carrier_stats = {}  # carrier_name -> {'total':0, 'ontime':0}

with open('bookstore_orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        # Filter for delivered orders
        if row['fulfillment_status'] != 'Delivered':
            continue
        carrier = row['carrier_name'].strip()
        if not carrier:
            carrier = 'Unknown'
        # Parse dates
        est_str = row['estimated_delivery_date']
        act_str = row['actual_delivery_date']
        est_date = parse_date(est_str)
        act_date = parse_date(act_str)
        # If either date missing, we cannot determine on-time; treat as not on-time? 
        # But we still count as delivered.
        # We'll only count as on-time if both dates present and act_date <= est_date.
        # Initialize carrier if not present
        if carrier not in carrier_stats:
            carrier_stats[carrier] = {'total': 0, 'ontime': 0}
        carrier_stats[carrier]['total'] += 1
        if est_date is not None and act_date is not None:
            if act_date <= est_date:
                carrier_stats[carrier]['ontime'] += 1

# Prepare results
results = []
for carrier, stats in carrier_stats.items():
    total = stats['total']
    ontime = stats['ontime']
    if total == 0:
        ontime_pct = 0.0
    else:
        ontime_pct = (ontime / total) * 100.0
    results.append({
        'CarrierName': carrier,
        'TotalDelivered': total,
        'OnTimeDelivered': ontime,
        'OnTimePct': round(ontime_pct, 2)
    })

# Sort by OnTimePct descending
results.sort(key=lambda x: x['OnTimePct'], reverse=True)

# Write CSV
output_file = 'carrier-otd.csv'
with open(output_file, 'w', newline='') as f:
    fieldnames = ['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct']
    writer = csv.DictWriter(f, fieldnames=fieldnames)
    writer.writeheader()
    for row in results:
        writer.writerow(row)

print(f"Carrier on-time delivery performance written to {output_file}")
print("Top carriers:")
for row in results[:5]:
    print(f"{row['CarrierName']}: {row['OnTimePct']}% ({row['OnTimeDelivered']}/{row['TotalDelivered']})")"}

{"path": "carrier_delivery_time.py", "content": "import csv
from datetime import datetime

def parse_datetime(dt_str):
    """Parse datetime string in format YYYY-MM-DD HH:MM:SS"""
    if not dt_str or dt_str.strip() == '':
        return None
    try:
        return datetime.strptime(dt_str.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None

# Initialize dictionary to hold carrier data: {carrier: {'total_hours': 0.0, 'count': 0}}
carrier_data = {}

with open('bookstore_orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        # Filter for delivered orders
        if row['fulfillment_status'] != 'Delivered':
            continue
        carrier = row['carrier_name'].strip()
        if not carrier:
            carrier = 'Unknown'
        # Parse timestamps
        order_time = parse_datetime(row['order_timestamp'])
        actual_time = parse_datetime(row['actual_delivery_date'])
        # If either is missing, skip this order for turnaround calculation?
        # But we are only counting delivered orders, and we expect both to be present.
        # If missing, we cannot compute turnaround, so we skip for average but still count as delivered?
        # The requirement: compute turnaround time for each order, then average.
        # If we cannot compute, we should not include in the average.
        if order_time is None or actual_time is None:
            # Skip this order for turnaround calculation
            continue
        # Compute difference in hours
        delta = actual_time - order_time
        hours = delta.total_seconds() / 3600.0
        # Update carrier data
        if carrier not in carrier_data:
            carrier_data[carrier] = {'total_hours': 0.0, 'count': 0}
        carrier_data[carrier]['total_hours'] += hours
        carrier_data[carrier]['count'] += 1

# Prepare results
results = []
for carrier, data in carrier_data.items():
    count = data['count']
    total_hours = data['total_hours']
    if count == 0:
        avg_hours = 0.0
    else:
        avg_hours = total_hours / count
    results.append({
        'CarrierName': carrier,
        'DeliveredOrders': count,
        'AvgDeliveryHours': round(avg_hours, 2)
    })

# Sort by AvgDeliveryHours ascending (fastest first)
results.sort(key=lambda x: x['AvgDeliveryHours'])

# Write CSV
output_file = 'carrier-delivery-time.csv'
with open(output_file, 'w', newline='') as f:
    fieldnames = ['CarrierName', 'DeliveredOrders', 'AvgDeliveryHours']
    writer = csv.DictWriter(f, fieldnames=fieldnames)
    writer.writeheader()
    for row in results:
        writer.writerow(row)

print(f"Carrier delivery time analysis written to {output_file}")
print("Carriers sorted by fastest average delivery time:")
for row in results:
    print(f"{row['CarrierName']}: {row['AvgDeliveryHours']} hours ({row['DeliveredOrders']} orders)")"}

