#!/usr/bin/env python3
"""
movegen.py: Simple chess move generator (pure Python, stdlib only).

Provides:
- legal_moves(fen: str) -> list[str]
- perft(fen: str, depth: int) -> int

Handles normal piece movement, captures, pawn double pushes, and castling.
Does not handle en passant, promotion, or check/pin legality.
