#!/usr/bin/env python3
"""
movegen.py: Simple chess move generator (pure Python, stdlib only).

Provides:
- legal_moves(fen: str) -> list[str]
- perft(fen: str, depth: int) -> int

Handles normal piece movement, captures, pawn double pushes, castling, and en passant.
Does not handle promotion, or check/pin legality.
"""

def _fen_to_board(fen: str):
    """Parse FEN, return (board, side, castling, ep) where board is 8x8 list of chars,
    side is 'w' or 'b', castling is a string (e.g., 'KQkq'), ep is a string like 'e3' or None."""
    parts = fen.split()
    board_str = parts[0]
    side = parts[1] if len(parts) > 1 else 'w'
    castling = parts[2] if len(parts) > 2 else ''
    ep = parts[3] if len(parts) > 3 and parts[3] != '-' else None
    ranks = board_str.split('/')
    board = []
    for rank in ranks:
        row = []
        for ch in rank:
            if ch.isdigit():
                row.extend(['.'] * int(ch))
            else:
                row.append(ch)
        board.append(row)
    # Ensure 8x8
    if len(board) != 8:
        raise ValueError("Invalid FEN: not 8 ranks")
    for row in board:
        if len(row) != 8:
            raise ValueError("Invalid FEN: rank not 8 squares")
    return board, side, castling, ep


def _board_to_fen(board, side, castling, ep):
    """Convert board, side, castling, and ep to a FEN string."""
    rows = []
    for row in board:
        empty = 0
        parts = []
        for ch in row:
            if ch == '.':
                empty += 1
            else:
                if empty:
                    parts.append(str(empty))
                    empty = 0
                parts.append(ch)
        if empty:
            parts.append(str(empty))
        rows.append(''.join(parts))
    board_str = '/'.join(rows)
    if ep is None:
        ep_str = '-'
    else:
        ep_str = ep
    return f"{board_str} {side} {castling or '-'} {ep_str} 0 1"


def _square_to_coord(square: str):
    """Convert e2 to (row, col) where row 0 is rank 8, col 0 is file a."""
    file = ord(square[0]) - ord('a')
    rank = int(square[1]) - 1
    row = 7 - rank  # because rank 1 is bottom (row 7)
    col = file
    return row, col


def _coord_to_square(row, col):
    """Convert (row, col) to e2."""
    file = chr(ord('a') + col)
    rank = str(8 - row)
    return f"{file}{rank}"


def _get_castling_rights(fen: str) -> str:
    """Extract castling rights from FEN (field 3)."""
    parts = fen.split()
    if len(parts) < 3:
        return ''
    return parts[2]


def _king_position(board, side):
    """Return (row, col) of the king of given side, or None if not found."""
    piece = 'K' if side == 'w' else 'k'
    for row in range(8):
        for col in range(8):
            if board[row][col] == piece:
                return row, col
    return None


def _is_square_attacked(board, square, attacker_side):
    """Return True if any piece of attacker_side attacks square.
    attacker_side: 'w' or 'b'.
    Uses pseudo‑legal moves (ignores castling, en passant, etc)."""
    target_row, target_col = square
    for row in range(8):
        for col in range(8):
            piece = board[row][col]
            if piece == '.':
                continue
            is_white = piece.isupper()
            if (is_white and attacker_side != 'w') or (not is_white and attacker_side != 'b'):
                continue
            for dst_row, dst_col in _piece_moves(board, attacker_side, row, col):
                if dst_row == target_row and dst_col == target_col:
                    return True
    return False


